        for (let j = 0; j < n - 1 - i; j++) {
            let swap = false;
            if (outScores[j] < outScores[j + 1]) {
                swap = true;
            } else if (outScores[j] === outScores[j + 1] && outNames[j] > outNames[j + 1]) {
                swap = true;
